const body = $input.item.json.body || $input.item.json;
if (!body.email || !body.email.includes('@')) {
  throw new Error('Validation Error: Valid contact email is required.');
}

const domain = body.email.split('@')[1];
const isFreeProvider = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'].includes(domain.toLowerCase());

return {
  json: {
    leadId: 'lead_' + Math.random().toString(36).substring(2, 10),
    fullName: body.name || 'Anonymous Prospect',
    email: body.email.toLowerCase().trim(),
    company: body.company || (isFreeProvider ? 'Independent / Unspecified' : domain.split('.')[0].toUpperCase()),
    domain: domain,
    isCorporate: !isFreeProvider,
    inquiryText: body.message || body.notes || 'Inquiry requested via site form.',
    timestamp: new Date().toISOString()
  }
};
